1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"sort"
11	)
12	
13	type pullRequest struct {
14		id     int
15		deps   []int
16		checks string
17	}
18	
19	type queueResult struct {
20		Waves   [][]int `json:"waves"`
21		Blocked []int   `json:"blocked"`
22	}
23	
24	func main() {
25		os.Exit(run(os.Stdin, os.Stdout, os.Stderr))
26	}
27	
28	func run(in io.Reader, out io.Writer, errOut io.Writer) int {
29		result, err := plan(in)
30		if err != nil {
31			_, _ = fmt.Fprintln(errOut, err)
32			return 2
33		}
34	
35		if err := json.NewEncoder(out).Encode(result); err != nil {
36			_, _ = fmt.Fprintln(errOut, "writing result: "+err.Error())
37			return 1
38		}
39		return 0
40	}
41	
42	func plan(in io.Reader) (queueResult, error) {
43		prs, err := decodeQueue(in)
44		if err != nil {
45			return queueResult{}, err
46		}
47	
48		byID := make(map[int]pullRequest, len(prs))
49		for _, pr := range prs {
50			if pr.id <= 0 {
51				return queueResult{}, fmt.Errorf("invalid PR id %d: IDs must be positive", pr.id)
52			}
53			if _, exists := byID[pr.id]; exists {
54				return queueResult{}, fmt.Errorf("duplicate PR id %d", pr.id)
55			}
56			if pr.checks != "pass" && pr.checks != "fail" && pr.checks != "pending" {
57				return queueResult{}, fmt.Errorf("PR %d has invalid checks status %q", pr.id, pr.checks)
58			}
59			byID[pr.id] = pr
60		}
61	
62		for _, pr := range prs {
63			for _, dep := range pr.deps {
64				if _, exists := byID[dep]; !exists {
65					return queueResult{}, fmt.Errorf("PR %d depends on missing PR %d", pr.id, dep)
66				}
67			}
68		}
69	
70		if cycleID, ok := findCycle(byID); ok {
71			return queueResult{}, fmt.Errorf("dependency cycle detected involving PR %d", cycleID)
72		}
73	
74		blocked := make(map[int]bool, len(byID))
75		var isBlocked func(int) bool
76		isBlocked = func(id int) bool {
77			if known, ok := blocked[id]; ok {
78				return known
79			}
80			pr := byID[id]
81			blocked[id] = pr.checks != "pass"
82			if !blocked[id] {
83				for _, dep := range pr.deps {
84					if isBlocked(dep) {
85						blocked[id] = true
86						break
87					}
88				}
89			}
90			return blocked[id]
91		}
92	
93		ids := sortedIDs(byID)
94		blockedIDs := make([]int, 0)
95		for _, id := range ids {
96			if isBlocked(id) {
97				blockedIDs = append(blockedIDs, id)
98			}
99		}
100	
101		scheduled := make(map[int]bool, len(byID))
102		waves := make([][]int, 0)
103		for {
104			wave := make([]int, 0)
105			for _, id := range ids {
106				if blocked[id] || scheduled[id] {
107					continue
108				}
109				ready := true
110				for _, dep := range byID[id].deps {
111					if !scheduled[dep] {
112						ready = false
113						break
114					}
115				}
116				if ready {
117					wave = append(wave, id)
118				}
119			}
120			if len(wave) == 0 {
121				break
122			}
123			for _, id := range wave {
124				scheduled[id] = true
125			}
126			waves = append(waves, wave)
127		}
128	
129		return queueResult{Waves: waves, Blocked: blockedIDs}, nil
130	}
131	
132	func decodeQueue(in io.Reader) ([]pullRequest, error) {
133		decoder := json.NewDecoder(in)
134		var raw json.RawMessage
135		if err := decoder.Decode(&raw); err != nil {
136			return nil, fmt.Errorf("invalid JSON input: %w", err)
137		}
138		if first := bytes.TrimSpace(raw); len(first) == 0 || first[0] != '{' {
139			return nil, errors.New("invalid input: top-level value must be a JSON object")
140		}
141	
142		var fields map[string]json.RawMessage
143		if err := json.Unmarshal(raw, &fields); err != nil {
144			return nil, fmt.Errorf("invalid JSON object: %w", err)
145		}
146		prsRaw, ok := fields["prs"]
147		if !ok {
148			return nil, errors.New("invalid input: missing prs array")
149		}
150		if first := bytes.TrimSpace(prsRaw); len(first) == 0 || first[0] != '[' {
151			return nil, errors.New("invalid input: prs must be an array")
152		}
153	
154		var rawPRs []json.RawMessage
155		if err := json.Unmarshal(prsRaw, &rawPRs); err != nil {
156			return nil, fmt.Errorf("invalid prs array: %w", err)
157		}
158		prs := make([]pullRequest, 0, len(rawPRs))
159		for index, rawPR := range rawPRs {
160			pr, err := decodePR(rawPR)
161			if err != nil {
162				return nil, fmt.Errorf("invalid PR at index %d: %w", index, err)
163			}
164			prs = append(prs, pr)
165		}
166	
167		var extra json.RawMessage
168		if err := decoder.Decode(&extra); err != io.EOF {
169			if err == nil {
170				return nil, errors.New("invalid input: extra JSON value after queue")
171			}
172			return nil, fmt.Errorf("invalid input after queue: %w", err)
173		}
174		return prs, nil
175	}
176	
177	func decodePR(raw json.RawMessage) (pullRequest, error) {
178		var fields map[string]json.RawMessage
179		if first := bytes.TrimSpace(raw); len(first) == 0 || first[0] != '{' {
180			return pullRequest{}, errors.New("PR must be a JSON object")
181		}
182		if err := json.Unmarshal(raw, &fields); err != nil {
183			return pullRequest{}, fmt.Errorf("PR must be a JSON object: %w", err)
184		}
185	
186		idRaw, ok := fields["id"]
187		if !ok {
188			return pullRequest{}, errors.New("missing id")
189		}
190		var id int
191		if err := json.Unmarshal(idRaw, &id); err != nil {
192			return pullRequest{}, fmt.Errorf("id must be an integer: %w", err)
193		}
194	
195		depsRaw, ok := fields["deps"]
196		if !ok {
197			return pullRequest{}, errors.New("missing deps array")
198		}
199		if first := bytes.TrimSpace(depsRaw); len(first) == 0 || first[0] != '[' {
200			return pullRequest{}, errors.New("deps must be an array")
201		}
202		var deps []int
203		if err := json.Unmarshal(depsRaw, &deps); err != nil {
204			return pullRequest{}, fmt.Errorf("deps must contain integers: %w", err)
205		}
206		if deps == nil {
207			deps = []int{}
208		}
209	
210		checksRaw, ok := fields["checks"]
211		if !ok {
212			return pullRequest{}, errors.New("missing checks status")
213		}
214		var checks string
215		if err := json.Unmarshal(checksRaw, &checks); err != nil {
216			return pullRequest{}, fmt.Errorf("checks must be a string: %w", err)
217		}
218	
219		return pullRequest{id: id, deps: deps, checks: checks}, nil
220	}
221	
222	func findCycle(byID map[int]pullRequest) (int, bool) {
223		state := make(map[int]uint8, len(byID))
224		ids := sortedIDs(byID)
225		var visit func(int) (int, bool)
226		visit = func(id int) (int, bool) {
227			switch state[id] {
228			case 1:
229				return id, true
230			case 2:
231				return 0, false
232			}
233			state[id] = 1
234			for _, dep := range byID[id].deps {
235				if cycleID, ok := visit(dep); ok {
236					return cycleID, true
237				}
238			}
239			state[id] = 2
240			return 0, false
241		}
242	
243		for _, id := range ids {
244			if cycleID, ok := visit(id); ok {
245				return cycleID, true
246			}
247		}
248		return 0, false
249	}
250	
251	func sortedIDs(byID map[int]pullRequest) []int {
252		ids := make([]int, 0, len(byID))
253		for id := range byID {
254			ids = append(ids, id)
255		}
256		sort.Ints(ids)
257		return ids
258	}
